package kz.studentgrades.controller;
import javafx.collections.*; import javafx.collections.transformation.FilteredList; import javafx.fxml.FXML; import javafx.fxml.FXMLLoader; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.stage.*;
import kz.studentgrades.Main; import kz.studentgrades.model.StudentGrade; import kz.studentgrades.service.GradeService;
import java.io.IOException; import java.util.*; import java.util.stream.Collectors;
public class MainController {
    @FXML private TableView<StudentGrade> gradeTable;
    @FXML private TableColumn<StudentGrade,String> studentColumn,groupColumn,subjectColumn,resultColumn;
    @FXML private TableColumn<StudentGrade,Number> scoreColumn;
    @FXML private TextField searchField; @FXML private ComboBox<String> groupFilter,subjectFilter; @FXML private Label averageLabel,statusLabel;
    private final GradeService service=new GradeService(); private final ObservableList<StudentGrade> all=FXCollections.observableArrayList(); private FilteredList<StudentGrade> filtered;
    @FXML public void initialize(){all.setAll(service.load());filtered=new FilteredList<>(all,g->true);gradeTable.setItems(filtered);
        studentColumn.setCellValueFactory(c->c.getValue().studentNameProperty());groupColumn.setCellValueFactory(c->c.getValue().groupNameProperty());subjectColumn.setCellValueFactory(c->c.getValue().subjectProperty());scoreColumn.setCellValueFactory(c->c.getValue().scoreProperty());resultColumn.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().getResult()));
        searchField.textProperty().addListener((o,a,b)->applyFilters());groupFilter.setOnAction(e->applyFilters());subjectFilter.setOnAction(e->applyFilters());refreshFilters();updateSummary();}
    @FXML private void add(){openForm(null);}
    @FXML private void edit(){StudentGrade s=gradeTable.getSelectionModel().getSelectedItem();if(s==null){alert("Выберите запись для изменения.");return;}openForm(s);}
    @FXML private void delete(){StudentGrade s=gradeTable.getSelectionModel().getSelectedItem();if(s==null){alert("Выберите запись для удаления.");return;}Alert a=new Alert(Alert.AlertType.CONFIRMATION,"Удалить запись студента "+s.getStudentName()+"?",ButtonType.YES,ButtonType.NO);a.setHeaderText("Подтверждение удаления");if(a.showAndWait().orElse(ButtonType.NO)==ButtonType.YES){all.remove(s);persist();refreshFilters();applyFilters();}}
    private void openForm(StudentGrade selected){try{FXMLLoader loader=new FXMLLoader(Main.class.getResource("grade-form.fxml"));Stage dialog=new Stage();dialog.setTitle(selected==null?"Добавить оценку":"Изменить оценку");dialog.initModality(Modality.APPLICATION_MODAL);dialog.setScene(new Scene(loader.load()));dialog.getScene().getStylesheets().add(Main.class.getResource("styles.css").toExternalForm());GradeFormController c=loader.getController();StudentGrade target=selected==null?null:new StudentGrade(selected.getStudentName(),selected.getGroupName(),selected.getSubject(),selected.getScore());c.setGrade(target);dialog.showAndWait();if(c.isSaved()){target=c.getGrade();if(selected==null)all.add(target);else{selected.setStudentName(target.getStudentName());selected.setGroupName(target.getGroupName());selected.setSubject(target.getSubject());selected.setScore(target.getScore());}persist();refreshFilters();applyFilters();gradeTable.refresh();}}catch(IOException e){alert("Не удалось открыть форму: "+e.getMessage());}}
    @FXML private void save(){persist();statusLabel.setText("Данные сохранены в data/grades.csv");}
    @FXML private void exit(){persist();((Stage)gradeTable.getScene().getWindow()).close();}
    @FXML private void showAbout(){new Alert(Alert.AlertType.INFORMATION,"Student Grade Calculator\nВариант 6 — журнал оценок студентов.").showAndWait();}
    private void persist(){try{service.save(new ArrayList<>(all));}catch(RuntimeException e){alert(e.getMessage());}updateSummary();}
    private void refreshFilters(){String oldG=groupFilter.getValue(),oldS=subjectFilter.getValue();groupFilter.getItems().setAll(all.stream().map(StudentGrade::getGroupName).distinct().sorted().collect(Collectors.toList()));subjectFilter.getItems().setAll(all.stream().map(StudentGrade::getSubject).distinct().sorted().collect(Collectors.toList()));groupFilter.getItems().add(0,"Все группы");subjectFilter.getItems().add(0,"Все дисциплины");groupFilter.setValue(oldG!=null&&groupFilter.getItems().contains(oldG)?oldG:"Все группы");subjectFilter.setValue(oldS!=null&&subjectFilter.getItems().contains(oldS)?oldS:"Все дисциплины");}
    private void applyFilters(){String q=searchField.getText()==null?"":searchField.getText().trim().toLowerCase();String g=groupFilter.getValue(),s=subjectFilter.getValue();filtered.setPredicate(x->(q.isEmpty()||x.getStudentName().toLowerCase().contains(q)||x.getSubject().toLowerCase().contains(q))&&(g==null||g.equals("Все группы")||g.equals(x.getGroupName()))&&(s==null||s.equals("Все дисциплины")||s.equals(x.getSubject())));updateSummary();}
    private void updateSummary(){double avg=filtered==null||filtered.isEmpty()?0:filtered.stream().mapToInt(StudentGrade::getScore).average().orElse(0);averageLabel.setText(String.format(Locale.US,"Средний балл: %.2f",avg));if(statusLabel!=null)statusLabel.setText("Показано: "+(filtered==null?0:filtered.size())+" из "+all.size());}
    private void alert(String message){new Alert(Alert.AlertType.INFORMATION,message).showAndWait();}
}
